sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

        try {
            //Get attributes values from request
            var payload = request.body.data;

            var num = payload.number;
            var corr_id = payload.correlation_id;
            var sh_desc = payload.short_description;
            var desc = payload.description;
            var impa = payload.impact;
            var urg = payload.urgency;

            //Short description is mandatory
            if (corr_id != '') {

                var myError = new sn_ws_err.ServiceError();
                myError.setStatus(442);
                myError.setMessage('Correlation_id must be empty');
                myError.setDetail('We cannot create the incident because correlation_id attribute you sent has value.');
                return myError;

            } else {

                var gr = new GlideRecord("incident");
                gr.addQuery('correlation_id', num);
                gr.query();

                if (gr.next()) {

                    var myError2 = new sn_ws_err.ServiceError();
                    myError2.setStatus(442);
                    myError2.setMessage('Check number attribute.');
                    myError2.setDetail('Check Incident number. We cannot create the incident because sent Incident number already exist in our database.');
                    return myError2;

                } else {

                gr.initialize();

                gr.correlation_id = num;
                gr.short_description = sh_desc;
                gr.description = desc;
                gr.impact = impa;
                gr.urgency = urg;

                gr.insert();

                response.setContentType('application/json');
                response.setBody({
                    Number: gr.number,
					Correlation_id: gr.correlation_id,
                    Short_Description: gr.short_description,
                    Result: "New incident hes been created"
                });

                response.setStatus(200);
            }
        }

    } catch (err) {
        var exp = new sn_ws_err.BadRequestError(err);
        response.setError(exp);
    }
})(request, response);
